import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Teacher Dashboard -> Transaction History (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/teacher-dashboard/transaction-history.md","filePath":"modules/teacher-dashboard/transaction-history.md"}'),s={name:"modules/teacher-dashboard/transaction-history.md"};function n(i,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="teacher-dashboard-transaction-history-deep" tabindex="-1">Teacher Dashboard -&gt; Transaction History (deep) <a class="header-anchor" href="#teacher-dashboard-transaction-history-deep" aria-label="Permalink to &quot;Teacher Dashboard -&gt; Transaction History (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>teacher-dashboard</code><br><strong>Feature:</strong> <code>transaction-history</code><br><strong>Route:</strong> <code>/teacher-dashboard/transaction-history</code></p><p>This page is the instructor-facing transaction ledger. It shows received amounts, payouts, and transaction history with filtering and pagination.</p><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/teacher-dashboard/InstructorTransactionHistoryPage.tsx</code></td><td>Main transaction-history page</td><td>Calls instructor transaction list/count/stats queries; renders stat cards, filter tabs, paginated table, and detail modal.</td></tr><tr><td><code>Frontend/src/graphql/Queries/transactionQueries.ts</code></td><td>Shared transaction GraphQL</td><td>Defines instructor transaction queries and counts.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/tabs/PaymentTab.tsx</code></td><td>Related older surface</td><td>Imports transaction queries too, but the live full history UI is the dedicated route page above.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-instructor-transactions" tabindex="-1"><code>GET_INSTRUCTOR_TRANSACTIONS</code> <a class="header-anchor" href="#get-instructor-transactions" aria-label="Permalink to &quot;`GET_INSTRUCTOR_TRANSACTIONS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/transactionQueries.ts</code></li><li>Query field: <code>getInstructorTransactions(limit, offset, type)</code></li><li>Used by: <code>InstructorTransactionHistoryPage.tsx</code></li></ul><h3 id="get-instructor-transactions-count" tabindex="-1"><code>GET_INSTRUCTOR_TRANSACTIONS_COUNT</code> <a class="header-anchor" href="#get-instructor-transactions-count" aria-label="Permalink to &quot;`GET_INSTRUCTOR_TRANSACTIONS_COUNT`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/transactionQueries.ts</code></li><li>Query field: <code>getInstructorTransactionCount(type)</code></li><li>Used by: pagination on <code>InstructorTransactionHistoryPage.tsx</code></li></ul><h3 id="get-instructor-transaction-stats" tabindex="-1"><code>GET_INSTRUCTOR_TRANSACTION_STATS</code> <a class="header-anchor" href="#get-instructor-transaction-stats" aria-label="Permalink to &quot;`GET_INSTRUCTOR_TRANSACTION_STATS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/transactionQueries.ts</code></li><li>Query field: <code>getInstructorTransactionStats</code></li><li>Used by: summary stat cards</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/transaction.typeDefs.js</code></li><li>Relevant query fields: <ul><li><code>getInstructorTransactions(limit, offset, type): [Transaction!]!</code></li><li><code>getInstructorTransactionCount(type): Int!</code></li><li><code>getInstructorTransactionStats: InstructorTransactionStats!</code></li></ul></li><li>Relevant types: <ul><li><code>Transaction</code></li><li><code>InstructorTransactionStats</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/transaction.resolver.js</code></li><li>Relevant resolvers: <ul><li><code>Query.getInstructorTransactions</code><ul><li>Instructor-only</li><li>Filters by current <code>user.id</code>, <code>role: &quot;instructor&quot;</code>, and optional type</li><li>Applies sort and pagination</li></ul></li><li><code>Query.getInstructorTransactionCount</code><ul><li>Instructor-only</li><li>Counts matching transactions for pagination</li></ul></li><li><code>Query.getInstructorTransactionStats</code><ul><li>Instructor-only</li><li>Aggregates totals for received payments, payouts, and counts</li></ul></li><li><code>Transaction.lessonSummary</code><ul><li>Loads booking slot context to show human-readable lesson date/time in the UI</li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/transaction.model.js</code></td><td>Primary transaction store</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Resolves <code>lessonSummary</code> from booking/slot data</td></tr><tr><td><code>server/src/services/transactionService.js</code></td><td>Creates many of the transaction rows shown here</td></tr><tr><td><code>server/src/routes/stripeWebhook.routes.js</code></td><td>Writes transaction-related state via Stripe events</td></tr><tr><td><code>server/src/jobs/payoutJob.js</code></td><td>Generates payout-side financial events</td></tr><tr><td><code>server/src/jobs/t48ChargeJob.js</code></td><td>Generates deferred payment-related events</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Instructor opens <code>/teacher-dashboard/transaction-history</code>.</li><li>Page loads: <ul><li>list query</li><li>count query</li><li>stats query</li></ul></li><li>Changing filter tab changes the <code>type</code> variable and reloads list/count.</li><li>Changing page sends a new <code>offset</code>.</li><li>Backend returns only the current instructor’s transactions.</li><li><code>lessonSummary</code> is resolved from booking/slot data so the UI can show which lesson each row belongs to.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>This is the live transaction-history surface for instructors.</li><li><code>PaymentTab.tsx</code> still imports transaction queries, but its history branch is effectively dormant compared with this dedicated page.</li></ul>',23)])])}const b=t(s,[["render",n]]);export{p as __pageData,b as default};
